use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
# [doc = " Provides a default [Hasher] with fixed keys."] # [doc = " This is typically used in conjunction with [BuildHasherDefault] to create"] # [doc = " [AHasher]s in order to hash the keys of the map."] # [doc = ""] # [doc = " Generally it is preferable to use [RandomState] instead, so that different"] # [doc = " hashmaps will have different keys. However if fixed keys are desirable this"] # [doc = " may be used instead."] # [doc = ""] # [doc = " # Example"] # [doc = " ```"] # [doc = " use std::hash::BuildHasherDefault;"] # [doc = " use ahash::{AHasher, RandomState};"] # [doc = " use std::collections::HashMap;"] # [doc = ""] # [doc = " let mut map: HashMap<i32, i32, BuildHasherDefault<AHasher>> = HashMap::default();"] # [doc = " map.insert(12, 34);"] # [doc = " ```"] # [doc = ""] # [doc = " [BuildHasherDefault]: std::hash::BuildHasherDefault"] # [doc = " [Hasher]: std::hash::Hasher"] # [doc = " [HashMap]: std::collections::HashMap"] impl Default for AHasher { # [doc = " Constructs a new [AHasher] with fixed keys."] # [doc = " If `std` is enabled these will be generated upon first invocation."] # [doc = " Otherwise if the `compile-time-rng`feature is enabled these will be generated at compile time."] # [doc = " If neither of these features are available, hardcoded constants will be used."] # [doc = ""] # [doc = " Because the values are fixed, different hashers will all hash elements the same way."] # [doc = " This could make hash values predictable, if DOS attacks are a concern. If this behaviour is"] # [doc = " not required, it may be preferable to use [RandomState] instead."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use ahash::AHasher;"] # [doc = " use std::hash::Hasher;"] # [doc = ""] # [doc = " let mut hasher_1 = AHasher::default();"] # [doc = " let mut hasher_2 = AHasher::default();"] # [doc = ""] # [doc = " hasher_1.write_u32(1234);"] # [doc = " hasher_2.write_u32(1234);"] # [doc = ""] # [doc = " assert_eq!(hasher_1.finish(), hasher_2.finish());"] # [doc = " ```"] # [inline] fn default () -> AHasher { RandomState :: with_fixed_keys () . build_hasher () } }
}